"use client";

import { useEffect, useRef, useState } from "react";
import {
  searchFeatures,
  buildFeatureParams,
  type FeatureSearchParams,
} from "@/services/workflow-backend";
import { adaptFeatureSummaries } from "@/features/workspaces/lib/workspaceAdapter";
import type { ParsedFeature } from "@/services/yaml-parser";
import type { BoardLoadError } from "../types";

const DEBOUNCE_MS = 300;

function isEmptyParams(params: FeatureSearchParams): boolean {
  return !params.title && !params.status;
}

export type UseBackendFeatureSearchResult = {
  results: ParsedFeature[] | null;
  searching: boolean;
  searchError: BoardLoadError | null;
};

export function useBackendFeatureSearch(
  workspaceId: string | null,
  params: FeatureSearchParams,
): UseBackendFeatureSearchResult {
  const [results, setResults] = useState<ParsedFeature[] | null>(null);
  const [searching, setSearching] = useState(false);
  const [searchError, setSearchError] = useState<BoardLoadError | null>(null);
  const requestIdRef = useRef(0);

  useEffect(() => {
    if (!workspaceId || isEmptyParams(params)) {
      setResults(null);
      setSearching(false);
      setSearchError(null);
      return;
    }

    let cancelled = false;
    const timer = setTimeout(async () => {
      const id = ++requestIdRef.current;
      setSearching(true);
      setSearchError(null);

      try {
        const features = await searchFeatures(workspaceId, buildFeatureParams(params));
        if (cancelled || requestIdRef.current !== id) return;
        setResults(adaptFeatureSummaries(features));
        setSearching(false);
      } catch (err: unknown) {
        if (cancelled || requestIdRef.current !== id) return;
        const e = err as { code?: string; message?: string; retryable?: boolean };
        setSearchError({
          kind: "network_error",
          message: e.message ?? "Feature search failed",
          retryable: e.retryable,
        });
        setResults([]);
        setSearching(false);
      }
    }, DEBOUNCE_MS);

    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [workspaceId, params.title, params.status]);

  return { results, searching, searchError };
}
"use client";

import { useEffect, useRef, useState } from "react";
import {
  searchWorkspaceTasks,
  buildTaskParams,
  type TaskSearchParams,
} from "@/services/workflow-backend";
import { adaptTaskSummariesToFeatures } from "@/features/workspaces/lib/workspaceAdapter";
import type { ParsedFeature } from "@/services/yaml-parser";
import type { BoardLoadError } from "../types";

const DEBOUNCE_MS = 300;

function isEmptyParams(params: TaskSearchParams): boolean {
  return !params.task_id && !params.title && !params.status;
}

export type UseBackendTaskSearchResult = {
  results: ParsedFeature[] | null;
  searching: boolean;
  searchError: BoardLoadError | null;
};

export function useBackendTaskSearch(
  workspaceId: string | null,
  params: TaskSearchParams,
): UseBackendTaskSearchResult {
  const [results, setResults] = useState<ParsedFeature[] | null>(null);
  const [searching, setSearching] = useState(false);
  const [searchError, setSearchError] = useState<BoardLoadError | null>(null);
  const requestIdRef = useRef(0);

  useEffect(() => {
    if (!workspaceId || isEmptyParams(params)) {
      setResults(null);
      setSearching(false);
      setSearchError(null);
      return;
    }

    let cancelled = false;
    const timer = setTimeout(async () => {
      const id = ++requestIdRef.current;
      setSearching(true);
      setSearchError(null);

      try {
        const tasks = await searchWorkspaceTasks(workspaceId, buildTaskParams(params));
        if (cancelled || requestIdRef.current !== id) return;
        setResults(adaptTaskSummariesToFeatures(tasks));
        setSearching(false);
      } catch (err: unknown) {
        if (cancelled || requestIdRef.current !== id) return;
        const e = err as { code?: string; message?: string; retryable?: boolean };
        setSearchError({
          kind: "network_error",
          message: e.message ?? "Task search failed",
          retryable: e.retryable,
        });
        setResults([]);
        setSearching(false);
      }
    }, DEBOUNCE_MS);

    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [workspaceId, params.task_id, params.title, params.status]);

  return { results, searching, searchError };
}
"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  searchWorkspaceTasks,
  SIDEBAR_TASK_PARAMS,
  type ApiError,
  type TaskSummary,
} from "@/services/workflow-backend";

const POLL_INTERVAL_MS = 60_000;

export type UseSidebarTasksResult = {
  tasks: TaskSummary[];
  loading: boolean;
  error: ApiError | null;
  reload: () => void;
};

export function useSidebarTasks(workspaceId: string | null): UseSidebarTasksResult {
  const [tasks, setTasks] = useState<TaskSummary[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<ApiError | null>(null);
  const [tick, setTick] = useState(0);
  const requestIdRef = useRef(0);

  const reload = useCallback(() => {
    setTick((t) => t + 1);
  }, []);

  useEffect(() => {
    if (!workspaceId) {
      setTasks([]);
      setLoading(false);
      setError(null);
      return;
    }

    let cancelled = false;
    const id = ++requestIdRef.current;
    setLoading(true);

    searchWorkspaceTasks(workspaceId, SIDEBAR_TASK_PARAMS)
      .then((result) => {
        if (cancelled || requestIdRef.current !== id) return;
        setTasks(result);
        setError(null);
        setLoading(false);
      })
      .catch((err: ApiError) => {
        if (cancelled || requestIdRef.current !== id) return;
        setError(err);
        setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [workspaceId, tick]);

  // Poll independently
  const reloadRef = useRef(reload);
  useEffect(() => {
    reloadRef.current = reload;
  }, [reload]);

  useEffect(() => {
    if (!workspaceId) return;
    const id = setInterval(() => {
      reloadRef.current();
    }, POLL_INTERVAL_MS);
    return () => clearInterval(id);
  }, [workspaceId]);

  return { tasks, loading, error, reload };
}

