"use client";

import { useMemo } from "react";
import { useBoardContext } from "../KanbanBoard/KanbanBoard.context";
import { FeatureRow } from "../FeatureRow";
import { STATUS_COLUMNS } from "../../lib/status";
import {
  matchesTaskModeSearch,
  matchesTaskModeStatusFilter,
} from "../../lib/filter";
import {
  AccessDeniedState,
  EmptyBoardState,
  NetworkErrorState,
  NoWorkflowDataState,
  ParseErrorState,
} from "../ErrorStates";
import type { ParsedFeature } from "@/services/yaml-parser";

function TaskColumnHeader({
  label,
  color,
  count,
}: {
  label: string;
  color: string;
  count: number;
}) {
  return (
    <div className="flex min-w-0 flex-1 items-center justify-between border-r border-border bg-surface-secondary px-3 py-2.5 last:border-r-0">
      <div className="flex min-w-0 items-center gap-2">
        <div
          className="h-2 w-2 rounded-sm"
          style={{ background: color }}
          aria-hidden="true"
        />
        <span className="truncate text-xs font-semibold uppercase tracking-wide text-text-secondary">
          {label}
        </span>
      </div>
      <span
        className="rounded px-1.5 py-0.5 text-xs font-semibold"
        style={{ color, background: `${color}18` }}
      >
        {count}
      </span>
    </div>
  );
}

function EmptyState({ message }: { message: string }) {
  return (
    <div className="flex flex-1 flex-col items-center justify-center gap-2 py-20">
      <p className="text-sm text-text-muted">{message}</p>
    </div>
  );
}

export function TaskBoardView() {
  const {
    features,
    loading,
    error,
    taskSearchQuery,
    taskActiveFilters,
    expandedFeatureIds,
    toggleFeature,
    setSelectedTask,
    backendTaskResults,
    taskSearching,
    taskSearchError,
  } = useBoardContext();

  // Use backend search results when a search is active; otherwise filter client-side
  const visibleFeatures = useMemo<ParsedFeature[]>(() => {
    if (backendTaskResults != null) return backendTaskResults;
    return features.filter(
      (f) =>
        matchesTaskModeSearch(f, taskSearchQuery) &&
        matchesTaskModeStatusFilter(f, taskActiveFilters.statuses),
    );
  }, [features, backendTaskResults, taskSearchQuery, taskActiveFilters]);

  const columnCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const col of STATUS_COLUMNS) counts[col.key] = 0;
    for (const feature of visibleFeatures) {
      for (const task of feature.tasks) {
        if (task.status in counts) counts[task.status]++;
      }
    }
    return counts;
  }, [visibleFeatures]);

  if (loading || taskSearching) {
    return (
      <div className="flex flex-1 items-center justify-center">
        <p className="text-sm text-text-muted">
          {taskSearching ? "Searching..." : "Loading board..."}
        </p>
      </div>
    );
  }

  const activeError = taskSearchError ?? error;
  if (activeError) {
    if (activeError.kind === "access_denied")
      return <AccessDeniedState message={activeError.message} />;
    if (activeError.kind === "not_found")
      return <NoWorkflowDataState message={activeError.message} />;
    if (activeError.kind === "parse_error")
      return <ParseErrorState message={activeError.message} />;
    return (
      <NetworkErrorState
        message={activeError.message}
        retryable={activeError.retryable}
      />
    );
  }

  if (features.length === 0 && backendTaskResults == null) return <EmptyBoardState />;

  if (visibleFeatures.length === 0) {
    return (
      <EmptyState message="No tasks match the current search or filters." />
    );
  }

  return (
    <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden">
      <div className="w-full">
        <div
          className="sticky top-0 z-10 flex w-full border-b border-border"
          role="row"
          aria-label="Status columns"
        >
          {STATUS_COLUMNS.map((col) => (
            <TaskColumnHeader
              key={col.key}
              label={col.label}
              color={col.color}
              count={columnCounts[col.key] ?? 0}
            />
          ))}
        </div>

        <div role="list" aria-label="Features" className="bg-surface">
          {visibleFeatures.map((feature) => (
            <div key={feature.id} role="listitem">
              <FeatureRow
                feature={feature}
                isExpanded={expandedFeatureIds.has(feature.id)}
                onToggle={() => toggleFeature(feature.id)}
                onSelectTask={setSelectedTask}
              />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
"use client";

import { useMemo } from "react";
import { useBoardContext } from "../KanbanBoard/KanbanBoard.context";
import { FeatureListRow } from "./FeatureListRow";
import type { ParsedFeature } from "@/services/yaml-parser";
import {
  matchesFeatureModeSearch,
  matchesFeatureModeStatusFilter,
} from "../../lib/filter";
import {
  FEATURE_STATUS_OPTIONS,
  getFeatureStatusColor,
  getFeatureStatusLabel,
} from "../../lib/status";
import {
  AccessDeniedState,
  EmptyBoardState,
  NetworkErrorState,
  NoWorkflowDataState,
  ParseErrorState,
} from "../ErrorStates";

const MIN_FEATURE_COLUMN_WIDTH = 180;

type FeatureStatusColumn = {
  key: string;
  label: string;
  color: string;
};

function getFeatureStatusColumns(
  features: ParsedFeature[],
): FeatureStatusColumn[] {
  const columns: FeatureStatusColumn[] = [...FEATURE_STATUS_OPTIONS];
  const knownStatuses = new Set(columns.map((column) => column.key));

  for (const feature of features) {
    if (knownStatuses.has(feature.featureStatus)) continue;
    knownStatuses.add(feature.featureStatus);
    columns.push({
      key: feature.featureStatus,
      label: getFeatureStatusLabel(feature.featureStatus),
      color: getFeatureStatusColor(feature.featureStatus),
    });
  }

  return columns;
}

function FeatureColumnHeader({
  statusKey,
  label,
  color,
  count,
}: {
  statusKey: string;
  label: string;
  color: string;
  count: number;
}) {
  return (
    <div
      data-feature-status-header={statusKey}
      className="flex min-w-0 items-center justify-between border-r border-border bg-surface-secondary px-3 py-2.5 last:border-r-0"
      style={{ minWidth: MIN_FEATURE_COLUMN_WIDTH }}
    >
      <div className="flex min-w-0 items-center gap-2">
        <span
          className="h-2 w-2 shrink-0 rounded-sm"
          style={{ background: color }}
          aria-hidden="true"
        />
        <span className="truncate text-xs font-semibold tracking-wide text-text-secondary">
          {label.toUpperCase()}
        </span>
      </div>
      <span
        data-feature-status-count={statusKey}
        className="rounded px-1.5 py-0.5 text-xs font-semibold"
        style={{ color, background: `${color}18` }}
      >
        {count}
      </span>
    </div>
  );
}

function EmptyState({ message }: { message: string }) {
  return (
    <div className="flex flex-1 flex-col items-center justify-center gap-2 py-20">
      <p className="text-sm text-text-muted">{message}</p>
    </div>
  );
}

export function FeatureBoardView() {
  const {
    features,
    loading,
    error,
    featureSearchQuery,
    featureActiveFilters,
    setSelectedFeature,
    backendFeatureResults,
    featureSearching,
    featureSearchError,
  } = useBoardContext();

  // Use backend search results when a search is active; otherwise filter client-side
  const visibleFeatures = useMemo(
    () => {
      if (backendFeatureResults != null) return backendFeatureResults;
      return features.filter(
        (f) =>
          matchesFeatureModeSearch(f, featureSearchQuery) &&
          matchesFeatureModeStatusFilter(f, featureActiveFilters.statuses),
      );
    },
    [features, backendFeatureResults, featureSearchQuery, featureActiveFilters],
  );

  const featureStatusColumns = useMemo(
    () => getFeatureStatusColumns(visibleFeatures),
    [visibleFeatures],
  );

  const featureStatusCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const column of featureStatusColumns) {
      counts[column.key] = 0;
    }

    for (const feature of visibleFeatures) {
      counts[feature.featureStatus] ??= 0;
      counts[feature.featureStatus] += 1;
    }

    return counts;
  }, [featureStatusColumns, visibleFeatures]);

  const activeError = featureSearchError ?? error;

  let content;
  if (loading || featureSearching) {
    content = (
      <div className="flex flex-1 items-center justify-center">
        <p className="text-sm text-text-muted">
          {featureSearching ? "Searching..." : "Loading features..."}
        </p>
      </div>
    );
  } else if (activeError) {
    if (activeError.kind === "access_denied") {
      content = <AccessDeniedState message={activeError.message} />;
    } else if (activeError.kind === "not_found") {
      content = <NoWorkflowDataState message={activeError.message} />;
    } else if (activeError.kind === "parse_error") {
      content = <ParseErrorState message={activeError.message} />;
    } else {
      content = (
        <NetworkErrorState
          message={activeError.message}
          retryable={activeError.retryable}
        />
      );
    }
  } else if (features.length === 0 && backendFeatureResults == null) {
    content = <EmptyBoardState />;
  } else if (visibleFeatures.length === 0) {
    content = (
      <EmptyState message="No features match the current search or filters." />
    );
  } else {
    const gridTemplateColumns = `repeat(${featureStatusColumns.length}, minmax(${MIN_FEATURE_COLUMN_WIDTH}px, 1fr))`;

    content = (
      <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden">
        <div
          data-feature-kanban-board
          className="min-h-full w-full"
          style={{
            minWidth: MIN_FEATURE_COLUMN_WIDTH * featureStatusColumns.length,
          }}
        >
          <div
            className="sticky top-0 z-10 grid w-full border-b border-border"
            role="row"
            aria-label="Feature status columns"
            style={{ gridTemplateColumns }}
          >
            {featureStatusColumns.map((column) => (
              <FeatureColumnHeader
                key={column.key}
                statusKey={column.key}
                label={column.label}
                color={column.color}
                count={featureStatusCounts[column.key] ?? 0}
              />
            ))}
          </div>

          <div role="list" aria-label="Features" className="bg-surface">
            {visibleFeatures.map((feature) => (
              <div
                key={feature.id}
                data-feature-grid-row
                role="listitem"
                className="grid min-h-[104px] border-b border-border"
                style={{ gridTemplateColumns }}
              >
                {featureStatusColumns.map((column) => (
                  <div
                    key={`${feature.id}-${column.key}`}
                    data-feature-status-cell
                    className="min-w-0 border-r border-border p-2 last:border-r-0"
                    role="cell"
                    aria-label={`${column.label} cell for ${feature.id}`}
                  >
                    {column.key === feature.featureStatus && (
                      <FeatureListRow
                        feature={feature}
                        onClick={() => setSelectedFeature(feature)}
                      />
                    )}
                  </div>
                ))}
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-full min-h-0 flex-1 flex-col overflow-hidden">
      {content}
    </div>
  );
}

