  clear: () => { Object.keys(store).forEach(k => { delete store[k]; }); },
};
// @ts-expect-error global patch
global.window = {};
// @ts-expect-error global patch
global.localStorage = mockLS;
import { getWorkspace, saveWorkspace, clearWorkspace } from "../services/workspace-store";
